{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching policies directly to IAM users increases the complexity of access management and the risk of excessive privileges. Policies should be attached to groups or roles instead."
    }
  ],
  "patched_code": "resource "aws_iam_group" "fn1-privesc3-group" {
  name = "fn1-privesc3-group"
}

resource "aws_iam_group_policy_attachment" "privesc3-passrole-group-attach-policy" {
  group      = aws_iam_group.fn1-privesc3-group.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn
}

resource "aws_iam_user_group_membership" "fn1-privesc3-user-group-membership" {
  user = aws_iam_user.fn1-privesc3-partial-user.name
  groups = [
    aws_iam_group.fn1-privesc3-group.name
  ]
}",
  "fix_summary": "Replaced the direct attachment of the policy to the IAM user with a group-based approach. Created a new IAM group, attached the policy to the group, and added the user to the group."
}
